import{_ as a,o as i,c as n,ag as l}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"14 · 备份与恢复","description":"","frontmatter":{"概念":"备份与恢复","技能":"database","阶段":"3-工程层","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"database/concepts/14-backup-recovery.md","filePath":"database/concepts/14-backup-recovery.md","lastUpdated":null}'),t={name:"database/concepts/14-backup-recovery.md"};function p(e,s,h,k,r,o){return i(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="_14-·-备份与恢复" tabindex="-1">14 · 备份与恢复 <a class="header-anchor" href="#_14-·-备份与恢复" aria-label="Permalink to &quot;14 · 备份与恢复&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>备份不是「每天导出一份文件」这么简单——它是一门关于<strong>恢复</strong>的工程:数据能恢复到多新(RPO)、恢复要多快(RTO)、恢复流程是否被验证过。没有 binlog 的备份只能恢复到备份那一刻,备份文件不演练等于没备份。前端对&quot;备份&quot;的理解通常是「代码 push 到 git、打包产物存 CI」,但数据库备份面对的是<strong>持续变化的数据</strong>,粒度、手段、验证方式完全不同。</p><p>本篇覆盖:逻辑备份 vs 物理备份、binlog 与增量备份、时间点恢复(PITR)完整实操、以及「备份演练」为什么是备份体系里最重要的一环。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-两种备份-逻辑备份与物理备份" tabindex="-1">1. 两种备份:逻辑备份与物理备份 <a class="header-anchor" href="#_1-两种备份-逻辑备份与物理备份" aria-label="Permalink to &quot;1. 两种备份:逻辑备份与物理备份&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 1a. 逻辑备份:mysqldump ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 产物是纯 SQL 文本(建表 + INSERT 语句),跨版本/跨平台可移植</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --single-transaction:InnoDB 下用一致性快照导出,备份期间不阻塞线上写入</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --master-data=2:把当前 binlog 位置写进备份文件的注释里——PITR 的起点,必须带</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqldump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --single-transaction</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-data=2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup_20260801.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 恢复:把 SQL 文件原样灌回去(目标库会先被清空/重建)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup_20260801.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 1b. 物理备份:直接拷贝数据文件 ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 逻辑备份大表极慢(逐行导出 INSERT),物理备份是文件级复制,快 10 倍以上</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 工具:Percona XtraBackup 或 MySQL Enterprise Backup</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># xtrabackup --backup --target-dir=/backup/full</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 物理备份恢复:同样文件级还原,需要停机或借助 binlog 追平</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 选型:小库(&lt; 50G)逻辑备份够用;大库/生产必须物理备份,恢复时间(RTO)才可控</span></span></code></pre></div><h4 id="_2-binlog-增量备份的基石" tabindex="-1">2. binlog:增量备份的基石 <a class="header-anchor" href="#_2-binlog-增量备份的基石" aria-label="Permalink to &quot;2. binlog:增量备份的基石&quot;">​</a></h4><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ---------- 2. binlog 是什么 ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- binlog(binary log)记录所有写入操作(增删改),是增量备份与 PITR 的前提</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 先确认开启了没有:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;log_bin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ON:已开启(生产必须 ON,否则只能恢复到备份时刻)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW VARIABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;binlog_format&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- ROW 推荐(记录行的前后镜像,可精确恢复)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BINARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOGS;                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 列出所有 binlog 文件(增量备份的&quot;目录&quot;)</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ---------- 2b. 备份组合:全量 + 增量 ----------</span></span>
<span class="line"><span># 日常节奏:</span></span>
<span class="line"><span>#   每天 02:00:全量备份(mysqldump 或物理备份)</span></span>
<span class="line"><span>#   每 30 分钟:增量备份(binlog 文件归档/复制到备份机)</span></span>
<span class="line"><span># 恢复时:</span></span>
<span class="line"><span>#   全量恢复 → 重放 02:00 之后的所有 binlog → 数据追到&quot;最后一个已归档的 binlog&quot;</span></span>
<span class="line"><span># 效果:RPO 从&quot;24 小时&quot;降到&quot;分钟级&quot;</span></span>
<span class="line"><span># 等价于前端:全量备份 ≈ 打一个发布 tag,binlog ≈ 之后每次提交的记录</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 2c. 备份文件命名与轮转 ----------</span></span>
<span class="line"><span># 命名建议:库名_日期_类型.sql,如 blog_20260801_full.sql / blog_binlog_000056.log</span></span>
<span class="line"><span># 保留策略:全量保留 30 天、binlog 保留 7 天(按 RPO/RTO 目标调整)</span></span>
<span class="line"><span># 验证手段:恢复前先校验文件完整性(mysqldump 后跟 gzip -t / mysql 语法检查)</span></span></code></pre></div><h4 id="_3-时间点恢复-pitr-完整实操" tabindex="-1">3. 时间点恢复(PITR)完整实操 <a class="header-anchor" href="#_3-时间点恢复-pitr-完整实操" aria-label="Permalink to &quot;3. 时间点恢复(PITR)完整实操&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 3. 场景:今天 14:00 误删了 orders 表 ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 已知:昨晚 02:00 全量备份 backup_20260731.sql;binlog 已归档到 backup-server</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 步骤一:把全量备份恢复到新实例(或临时库),回到 02:00 的状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup_20260731.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 步骤二:重放 02:00 之后的所有 binlog,停在误删发生的 14:00 之前</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --start-datetime 与 --stop-datetime 精确指定时间窗口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysqlbinlog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --start-datetime=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-01 02:00:00&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            --stop-datetime=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-01 14:00:00&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            /backup/binlog/mysql-bin.000056</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blog</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 更精确的恢复:还可以用 --stop-position 按 binlog 偏移量定位</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># mysqlbinlog --start-position=123456 --stop-position=456789 mysql-bin.000056 | mysql ...</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 注意:14:00 之后仍然在写入,恢复后会有&quot;恢复时段之后的新数据丢失&quot;,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 所以生产上 PITR 通常恢复到&quot;误删前几秒&quot;,再引导应用切换</span></span></code></pre></div><h4 id="_4-rpo-与-rto-备份目标的量化" tabindex="-1">4. RPO 与 RTO:备份目标的量化 <a class="header-anchor" href="#_4-rpo-与-rto-备份目标的量化" aria-label="Permalink to &quot;4. RPO 与 RTO:备份目标的量化&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ---------- 4. 两个指标决定备份策略 ----------</span></span>
<span class="line"><span># RPO(Recovery Point Objective):能容忍丢多少数据</span></span>
<span class="line"><span>#   - 全量每天一次,无增量   → RPO = 24 小时</span></span>
<span class="line"><span>#   - 全量 + binlog 实时归档 → RPO ≈ 0(丢失秒级)</span></span>
<span class="line"><span># RTO(Recovery Time Objective):恢复要多快</span></span>
<span class="line"><span>#   - 全量 2 小时 + binlog 重放 30 分钟 → RTO ≈ 2.5 小时</span></span>
<span class="line"><span># 备份策略 = 在成本(备份存储、归档带宽、备份对线上的压力)</span></span>
<span class="line"><span>#           与 RPO/RTO 目标之间取平衡,并且写进文档、能被量化验收</span></span>
<span class="line"><span># 不同业务不同目标:订单库 RPO=0;埋点日志库 RPO=24h 也可以</span></span></code></pre></div><h4 id="_5-备份演练-没验证过的备份等于没有备份" tabindex="-1">5. 备份演练:没验证过的备份等于没有备份 <a class="header-anchor" href="#_5-备份演练-没验证过的备份等于没有备份" aria-label="Permalink to &quot;5. 备份演练:没验证过的备份等于没有备份&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 5. 演练是备份体系的一部分 ----------</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每月一次&quot;恢复演练&quot;,流程:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 从备份 + binlog 完整恢复一份&quot;影子库&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 对影子库跑关键查询与数据校验(条数、金额汇总、关键表抽查)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 记录实际 RTO,与目标对比;发现恢复链路问题立即修</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 把演练脚本沉淀成文档/自动化,新人照着也能恢复</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 演练常发现的问题:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   - 备份文件损坏/不完整(没校验直接覆盖了)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   - 恢复步骤依赖某个人的&quot;经验记忆&quot;,没写成文档</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   - binlog 归档链路断了一周没人发现 → 演练时才发现 RPO 早已变 7 天</span></span></code></pre></div><p><strong>要点</strong>:备份三件套 = 全量备份 + binlog 增量 + 定期演练;PITR = 全量恢复 + binlog 重放到指定时间点;RPO/RTO 是量化目标,演练是唯一验证手段。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>只备份不演练</strong>:恢复脚本从未跑过,真出事时才发现备份文件损坏、权限缺失、binlog 没归档。</li><li><strong>备份文件与数据库同机存放</strong>:硬盘一坏,备份和主库一起没;必须异机/异地。</li><li><strong>没开 binlog</strong>:只能恢复到备份那一刻,事故后几小时数据永久丢失;开 binlog 是底线配置。</li><li><strong>备份后不校验</strong>:mysqldump 建议加 <code>--single-transaction</code> 之外,恢复前先 <code>mysql &lt; dump.sql</code> 到临时库验证,或对比 checksum。</li><li><strong>大表用 mysqldump 全量备份</strong>:几小时导出拖垮线上;大库切物理备份(XtraBackup)并按表拆分。</li><li><strong>演练只测「能恢复」不测「恢复多快」</strong>:RTO 是目标不是口号,演练记录真实耗时并对比。</li><li><strong>权限不分家</strong>:能删库的账号不备份,能备份的账号能删库——备份体系里,权限管理与备份同等重要。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>:本地起 MySQL(开 binlog),建库建表插 100 行数据,做一次带 <code>--master-data=2</code> 的 mysqldump 全量备份,再 DROP 库,从备份完整恢复并校验数据。</li><li><strong>进阶</strong>:模拟 PITR——全量备份后继续插入数据并记录时间,然后误删表;用 <code>mysqlbinlog</code> 重放到误删前的时间点,验证数据恢复到「一秒不差」;对比不同 <code>--binlog_format</code>(STATEMENT/ROW)对恢复结果的影响。</li><li><strong>综合</strong>:为一套假想电商库设计备份方案:定义 RPO/RTO 目标、备份调度(全量/增量/异机归档)、恢复手册(SOP 文档),并写一个每月自动恢复演练的脚本(恢复影子库 + 关键指标校验 + 输出报告)。</li></ol><blockquote><p>用 <code>/practice database 备份与恢复</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>数据库</th></tr></thead><tbody><tr><td>git 提交历史</td><td>binlog 变更日志</td></tr><tr><td>git 回滚到某个 commit</td><td>PITR 恢复到某个时间点</td></tr><tr><td>发布 tag 存档(dist)</td><td>全量备份</td></tr><tr><td>CI 产物保留策略</td><td>RPO/RTO 备份策略</td></tr><tr><td>发版后回滚预案演练</td><td>恢复演练</td></tr><tr><td>localStorage 导出 JSON</td><td>逻辑备份(mysqldump)</td></tr><tr><td>部署机异地备份镜像</td><td>物理备份(文件级)</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://dev.mysql.com/doc/refman/8.0/en/mysqldump.html" target="_blank" rel="noreferrer">MySQL mysqldump 官方文档</a></li><li><a href="https://dev.mysql.com/doc/refman/8.0/en/binary-log.html" target="_blank" rel="noreferrer">MySQL binlog 官方文档</a></li><li><a href="https://docs.percona.com/percona-xtrabackup/" target="_blank" rel="noreferrer">Percona XtraBackup 文档</a></li><li><a href="https://www.postgresql.org/docs/current/backup.html" target="_blank" rel="noreferrer">PostgreSQL 备份与恢复官方文档</a></li></ul>`,26)])])}const g=a(t,[["render",p]]);export{c as __pageData,g as default};
